import{_ as i,c as t,o as r,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"STRENGTHENING PROBATIONARY PERIODS IN THE FEDERAL SERVICE","description":"","frontmatter":{"title":"STRENGTHENING PROBATIONARY PERIODS IN THE FEDERAL SERVICE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/strengthening-probationary-periods-in-the-federal-service/","publishDate":"2025-04-24T17:22:29-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-24-strengthening-probationary-periods-in-the-federal-service.md","filePath":"executive-orders/2025-04-24-strengthening-probationary-periods-in-the-federal-service.md"}'),a={name:"executive-orders/2025-04-24-strengthening-probationary-periods-in-the-federal-service.md"};function o(s,e,l,d,p,c){return r(),t("div",null,e[0]||(e[0]=[n('<h1 id="strengthening-probationary-periods-in-the-federal-service" tabindex="-1">STRENGTHENING PROBATIONARY PERIODS IN THE FEDERAL SERVICE <a class="header-anchor" href="#strengthening-probationary-periods-in-the-federal-service" aria-label="Permalink to &quot;STRENGTHENING PROBATIONARY PERIODS IN THE FEDERAL SERVICE&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/strengthening-probationary-periods-in-the-federal-service/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/strengthening-probationary-periods-in-the-federal-service/</a></p><p>Published: Thursday, April 24, 2025</p><ul><li>The executive order aims to improve the effectiveness of the federal workforce by ensuring probationary and trial periods are utilized properly to assess new employees.</li><li>Agencies have not been effectively using these periods, resulting in the retention of underperforming employees.</li><li>The order mandates that agencies must approve the tenure of probationary employees before they can gain permanent status.</li><li>A new Civil Service Rule XI replaces previous regulations and requires agencies to affirmatively determine that continued employment benefits the federal service before finalizing appointments.</li><li>Specific sections of existing regulations that limit agency action regarding probationary periods are removed to allow for better management.</li><li>Civil Service Rule XI consists of several sections detailing the policies regarding probationary and trial periods, including definitions, conditions for completion, appeals processes, and how to credit prior service.</li><li>Agencies are instructed to identify employees in initial probationary or trial periods and designate individuals responsible for evaluating their continued employment.</li><li>There is a requirement for agencies to meet with employees during their probationary periods to discuss performance and public interest considerations.</li><li>The order emphasizes that continued employment must be certified as beneficial to the public interest prior to finalizing an employee’s appointment.</li><li>The order is effective immediately, with certain requirements taking effect 90 days later.</li><li>It clarifies that it does not create enforceable rights against the United States or its entities.</li></ul>',4)]))}const g=i(a,[["render",o]]);export{f as __pageData,g as default};
